/** Mirrors the native Classic gallery controls observed in the live DOM. */
export function galleryFixture(total=2,options:{stuck?:boolean;badSlide?:number;duplicate?:boolean}={}){
 const ids=Array.from({length:total},(_,i)=>'image'+i);
 return `<div class="thing" data-fullname="t3_abc" data-url="https://www.reddit.com/gallery/abc"><div class="media-preview" data-media-ids="${ids.join(',')}"><div class="media-gallery"><div class="gallery-grid">${ids.map((_,i)=>`<button class="gallery-tile" onclick="show(${i})">Open image ${i+1}</button>`).join('')}</div>${ids.map((id,i)=>`<div class="gallery-preview" id="gallery-preview-abc-${id}" style="display:none"><ul class="gallery-nav-bar"><li class="gallery-nav-next ${i===total-1?'gallery-nav-disabled':''}" ${i<total-1?`onclick="show(${options.stuck?i:i+1})"`:''}>Next</li></ul><div class="media-preview-content"><a href="${i===options.badSlide?'https://evil.test/file.jpg':`https://i.redd.it/gallery${options.duplicate?0:i}.jpg`}"><img src="https://preview.redd.it/thumb${i}.jpg?width=960" width="300" height="200"></a><p>Caption ${i+1}</p></div></div>`).join('')}</div></div></div><script>function show(i){document.querySelector('.gallery-grid').style.display='none';document.querySelectorAll('.gallery-preview').forEach((e,n)=>e.style.display=n===i?'block':'none');}</script>`;
}
